cat > "$TS" <<'EOF'
import L from "leaflet";

type Point = { id: number; lat: number; lon: number };
type Scenario = { name: string; center: [number, number]; zoom: number };

declare global { interface Window { runMarkerProjectionBenchmark: () => unknown } }

const map = L.map("map", { attributionControl: false, fadeAnimation: false, markerZoomAnimation: false, zoomAnimation: false, zoomControl: false }).setView([51.1079, 17.0385], 13);

function generatePoints(count: number): Point[] {
  let state = 0x5eed1234;
  const next = () => { state = (Math.imul(state, 1664525) + 1013904223) >>> 0; return state / 0x100000000; };
  return Array.from({ length: count }, (_, id) => ({ id, lat: 49 + next() * 6, lon: 14 + next() * 10 }));
}

function currentPath(points: Point[]) {
  const size = map.getSize();
  let visible = 0;
  for (const item of points) {
    const point = map.latLngToContainerPoint([item.lat, item.lon]);
    if (point.x >= 0 && point.x <= size.x && point.y >= 0 && point.y <= size.y) visible += 1;
  }
  return { projectionCalls: points.length, visible };
}

function boundsPrefilterPath(points: Point[]) {
  const size = map.getSize();
  const bounds = map.getBounds();
  let projectionCalls = 0;
  let visible = 0;
  for (const item of points) {
    if (!bounds.contains([item.lat, item.lon])) continue;
    projectionCalls += 1;
    const point = map.latLngToContainerPoint([item.lat, item.lon]);
    if (point.x >= 0 && point.x <= size.x && point.y >= 0 && point.y <= size.y) visible += 1;
  }
  return { projectionCalls, visible };
}

function median(values: number[]) { const sorted = [...values].sort((a,b)=>a-b); return sorted[Math.floor(sorted.length / 2)]; }
function measure(fn: (points: Point[]) => unknown, points: Point[], rounds = 12) {
  for (let i = 0; i < 3; i += 1) fn(points);
  const samples: number[] = [];
  for (let i = 0; i < rounds; i += 1) { const start = performance.now(); fn(points); samples.push(performance.now() - start); }
  return Math.round(median(samples) * 1000) / 1000;
}

window.runMarkerProjectionBenchmark = () => {
  const scenarios: Scenario[] = [
    { name: "city-z13", center: [51.1079, 17.0385], zoom: 13 },
    { name: "metro-z9", center: [51.1079, 17.0385], zoom: 9 },
    { name: "regional-z6", center: [52.1, 19.4], zoom: 6 },
  ];
  const counts = [1000, 10000, 50000];
  const rows = [];
  for (const count of counts) {
    const points = generatePoints(count);
    for (const scenario of scenarios) {
      map.setView(scenario.center, scenario.zoom, { animate: false });
      map.invalidateSize({ animate: false });
      const currentResult = currentPath(points);
      const candidateResult = boundsPrefilterPath(points);
      rows.push({
        count,
        scenario: scenario.name,
        currentMs: measure(currentPath, points),
        candidateMs: measure(boundsPrefilterPath, points),
        currentProjectionCalls: currentResult.projectionCalls,
        candidateProjectionCalls: candidateResult.projectionCalls,
        currentVisible: currentResult.visible,
        candidateVisible: candidateResult.visible,
        equivalentVisibleCount: currentResult.visible === candidateResult.visible,
      });
    }
  }
  return rows;
};
EOF
